  CALL sp(p1,p2,p3,p4,p5,p6);
  INSERT INTO results SELECT tag, 'club', Club_ID::text, Club_name, Region, Start_year::text FROM club;
  INSERT INTO results SELECT tag, 'player', Player_ID::text, Sponsor_name, Player_name, Occupation FROM player;
